-- Seed problem_details using subqueries checking if problem was successfully created
INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Count occurrences and compute combinations.', 'Calculate sum of n*(n-1)/2 for each element count.', 'class Solution {\n    public int numIdenticalPairs(int[] nums) {\n        int ans = 0;\n        int[] count = new int[101];\n        for(int x : nums) ans += count[x]++;\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1)', 'Frequency combinations' FROM problems WHERE leetcode_number = 1512 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Extract digits and form smallest numbers.', 'Sort digits and combine into two numbers.', 'class Solution {\n    public int minimumSum(int num) {\n        int[] dig = new int[4];\n        for(int i=0; i<4; i++) { dig[i] = num % 10; num /= 10; }\n        Arrays.sort(dig);\n        return (dig[0]*10 + dig[2]) + (dig[1]*10 + dig[3]);\n    }\n}', 'Time: O(1), Space: O(1)', 'Sorting coordinates' FROM problems WHERE leetcode_number = 2160 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Integer division binary search.', 'Find max value x where x*x <= target.', 'class Solution {\n    public int mySqrt(int x) {\n        if(x == 0) return 0;\n        int l = 1, r = x, ans = 0;\n        while(l <= r){\n            int m = l + (r - l)/2;\n            if(m <= x / m) { ans = m; l = m + 1; } \n            else r = m - 1;\n        }\n        return ans;\n    }\n}', 'Time: O(log N), Space: O(1)', 'Check division to prevent overflow' FROM problems WHERE leetcode_number = 69 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Keep write pointer.', 'Shift non-zero items to write pointer, fill rest with zeros.', 'class Solution {\n    public void moveZeroes(int[] nums) {\n        int k = 0;\n        for(int x : nums) if(x != 0) nums[k++] = x;\n        while(k < nums.length) nums[k++] = 0;\n    }\n}', 'Time: O(N), Space: O(1)', 'Write indexes' FROM problems WHERE leetcode_number = 283 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Alternate elements.', 'Iterate and load x and y items sequentially.', 'class Solution {\n    public int[] shuffle(int[] nums, int n) {\n        int[] ans = new int[2*n];\n        for(int i=0; i<n; i++){\n            ans[2*i] = nums[i];\n            ans[2*i+1] = nums[i+n];\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(N)', 'Interleaving indexes' FROM problems WHERE leetcode_number = 1470 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Count matching balances.', 'Check character matches balance increments/decrements.', 'class Solution {\n    public int balancedStringSplit(String s) {\n        int ans = 0, bal = 0;\n        for(char c : s.toCharArray()){\n            bal += (c == ''L'') ? 1 : -1;\n            if(bal == 0) ans++;\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1)', 'Balanced splits' FROM problems WHERE leetcode_number = 1221 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Track min and max product.', 'DP tracking running minimum and maximum products to handle signs.', 'class Solution {\n    public int maxProduct(int[] nums) {\n        int max = nums[0], min = nums[0], ans = nums[0];\n        for(int i=1; i<nums.length; i++){\n            int t1 = nums[i] * max, t2 = nums[i] * min;\n            max = Math.max(nums[i], Math.max(t1, t2));\n            min = Math.min(nums[i], Math.min(t1, t2));\n            ans = Math.max(ans, max);\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1)', 'Product sign swaps' FROM problems WHERE leetcode_number = 152 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Rearrange grid axes.', 'Map mat[i][j] to transpose[j][i].', 'class Solution {\n    public int[][] transpose(int[][] matrix) {\n        int R = matrix.length, C = matrix[0].length;\n        int[][] ans = new int[C][R];\n        for(int r=0; r<R; r++){\n            for(int c=0; c<C; c++) ans[c][r] = matrix[r][c];\n        }\n        return ans;\n    }\n}', 'Time: O(R*C), Space: O(R*C)', 'Dimension flips' FROM problems WHERE leetcode_number = 867 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Map sums frequencies.', 'Use prefix sum counts to retrieve sub-arrays matching sum target.', 'class Solution {\n    public int subarraySum(int[] nums, int k) {\n        int count = 0, sum = 0;\n        Map<Integer, Integer> map = new HashMap<>();\n        map.put(0, 1);\n        for(int x : nums){\n            sum += x;\n            if(map.containsKey(sum - k)) count += map.get(sum - k);\n            map.put(sum, map.getOrDefault(sum, 0) + 1);\n        }\n        return count;\n    }\n}', 'Time: O(N), Space: O(N)', 'Subarray sum complement mappings' FROM problems WHERE leetcode_number = 560 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Prefix products.', 'Construct left prefix product and multiply with right suffix product.', 'class Solution {\n    public int[] productExceptSelf(int[] nums) {\n        int n = nums.length;\n        int[] ans = new int[n];\n        ans[0] = 1;\n        for(int i=1; i<n; i++) ans[i] = ans[i-1] * nums[i-1];\n        int right = 1;\n        for(int i=n-1; i>=0; i--){\n            ans[i] *= right;\n            right *= nums[i];\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1) auxiliary', 'In-place array modifications' FROM problems WHERE leetcode_number = 238 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Double pointer allowance.', 'Allow write pointers to track duplicate limits up to 2.', 'class Solution {\n    public int removeDuplicates(int[] nums) {\n        int k = 0;\n        for(int x : nums){\n            if(k < 2 || x != nums[k-2]) nums[k++] = x;\n        }\n        return k;\n    }\n}', 'Time: O(N), Space: O(1)', 'Conditional indexing bounds' FROM problems WHERE leetcode_number = 80 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Traverse spiral boundaries.', 'Fill matrix layers top-to-bottom, left-to-right.', 'class Solution {\n    public int[][] generateMatrix(int n) {\n        int[][] ans = new int[n][n];\n        int r1 = 0, r2 = n-1, c1 = 0, c2 = n-1, val = 1;\n        while(r1 <= r2 && c1 <= c2){\n            for(int c=c1; c<=c2; c++) ans[r1][c] = val++;\n            for(int r=r1+1; r<=r2; r++) ans[r][c2] = val++;\n            for(int c=c2-1; c>=c1; c--) ans[r2][c] = val++;\n            for(int r=r2-1; r>r1; r--) ans[r][c1] = val++;\n            r1++; r2--; c1++; c2--;\n        }\n        return ans;\n    }\n}', 'Time: O(N^2), Space: O(1) external', 'Layer boundary shrinkage' FROM problems WHERE leetcode_number = 59 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Two pointer bounds.', 'Compare squared values of endpoints and move inwards.', 'class Solution {\n    public int[] sortedSquares(int[] nums) {\n        int n = nums.length;\n        int[] ans = new int[n];\n        int l = 0, r = n-1, p = n-1;\n        while(l <= r){\n            if(Math.abs(nums[l]) > Math.abs(nums[r])){\n                ans[p--] = nums[l]*nums[l]; l++;\n            } else {\n                ans[p--] = nums[r]*nums[r]; r--;\n            }\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(N)', 'Decreasing pointer tracking' FROM problems WHERE leetcode_number = 977 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Iterative vertical check.', 'Compare characters index by index across all strings.', 'class Solution {\n    public String longestCommonPrefix(String[] strs) {\n        if(strs == null || strs.length == 0) return "";\n        for(int i=0; i<strs[0].length(); i++){\n            char c = strs[0].charAt(i);\n            for(int j=1; j<strs.length; j++){\n                if(i == strs[j].length() || strs[j].charAt(i) != c) return strs[0].substring(0, i);\n            }\n        }\n        return strs[0];\n    }\n}', 'Time: O(S) where S is sum of chars, Space: O(1)', 'Out of bounds checks' FROM problems WHERE leetcode_number = 14 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Scan backwards.', 'Find last word boundaries starting from end.', 'class Solution {\n    public int lengthOfLastWord(String s) {\n        int p = s.length() - 1, len = 0;\n        while(p >= 0 && s.charAt(p) == '' '') p--;\n        while(p >= 0 && s.charAt(p) != '' '') { len++; p--; }\n        return len;\n    }\n}', 'Time: O(N), Space: O(1)', 'Trailing spaces' FROM problems WHERE leetcode_number = 58 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Binary search peak.', 'Peak exists at mid if mid > mid+1, else search right.', 'class Solution {\n    public int findPeakElement(int[] nums) {\n        int l = 0, r = nums.length - 1;\n        while(l < r){\n            int m = l + (r - l)/2;\n            if(nums[m] > nums[m+1]) r = m;\n            else l = m + 1;\n        }\n        return l;\n    }\n}', 'Time: O(log N), Space: O(1)', 'Peak boundaries' FROM problems WHERE leetcode_number = 162 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Virtual 1D array map.', 'Map index to mat[index / C][index % C] coordinate values.', 'class Solution {\n    public boolean searchMatrix(int[][] matrix, int target) {\n        int R = matrix.length, C = matrix[0].length;\n        int l = 0, r = R*C - 1;\n        while(l <= r){\n            int m = l + (r - l)/2;\n            int val = matrix[m / C][m % C];\n            if(val == target) return true;\n            if(val < target) l = m + 1;\n            else r = m - 1;\n        }\n        return false;\n    }\n}', 'Time: O(log R*C), Space: O(1)', 'Grid coordinates math' FROM problems WHERE leetcode_number = 74 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Dictionary checks.', 'Count letter frequencies in magazine, subtract from note.', 'class Solution {\n    public boolean canConstruct(String ransomNote, String magazine) {\n        int[] count = new int[26];\n        for(char c : magazine.toCharArray()) count[c - ''a'']++;\n        for(char c : ransomNote.toCharArray()){\n            if(--count[c - ''a''] < 0) return false;\n        }\n        return true;\n    }\n}', 'Time: O(N+M), Space: O(1)', 'Frequency buckets' FROM problems WHERE leetcode_number = 383 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Sorted characters as key.', 'Use sorted char array as key to store matching anagram values.', 'class Solution {\n    public List<List<String>> groupAnagrams(String[] strs) {\n        Map<String, List<String>> map = new HashMap<>();\n        for(String s : strs){\n            char[] ch = s.toCharArray(); Arrays.sort(ch);\n            String key = String.valueOf(ch);\n            map.computeIfAbsent(key, k -> new ArrayList<>()).add(s);\n        }\n        return new ArrayList<>(map.values());\n    }\n}', 'Time: O(N * L log L), Space: O(N*L)', 'Sorting keys' FROM problems WHERE leetcode_number = 49 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Sort and two pointers.', 'Loop item i, adjust left/right pointers to find sums matching -nums[i].', 'class Solution {\n    public List<List<Integer>> threeSum(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        Arrays.sort(nums);\n        for(int i=0; i<nums.length-2; i++){\n            if(i > 0 && nums[i] == nums[i-1]) continue;\n            int l = i+1, r = nums.length - 1;\n            while(l < r){\n                int sum = nums[i] + nums[l] + nums[r];\n                if(sum == 0){\n                    ans.add(Arrays.asList(nums[i], nums[l], nums[r]));\n                    while(l<r && nums[l] == nums[l+1]) l++;\n                    while(l<r && nums[r] == nums[r-1]) r--;\n                    l++; r--;\n                } else if(sum < 0) l++;\n                else r--;\n            }\n        }\n        return ans;\n    }\n}', 'Time: O(N^2), Space: O(log N) sorting', 'Unique duplicates checks' FROM problems WHERE leetcode_number = 15 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Boundary heights comparison.', 'Track left_max and right_max bounds, compute water height.', 'class Solution {\n    public int trap(int[] height) {\n        int l = 0, r = height.length - 1, ans = 0;\n        int leftMax = 0, rightMax = 0;\n        while(l < r){\n            if(height[l] < height[r]){\n                if(height[l] >= leftMax) leftMax = height[l];\n                else ans += leftMax - height[l];\n                l++;\n            } else {\n                if(height[r] >= rightMax) rightMax = height[r];\n                else ans += rightMax - height[r];\n                r--;\n            }\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1)', 'Boundary checks' FROM problems WHERE leetcode_number = 42 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Vowels balance checks.', 'Maintain count of vowel occurrences inside K sliding window.', 'class Solution {\n    public int maxVowels(String s, int k) {\n        int max = 0, count = 0;\n        for(int i=0; i<s.length(); i++){\n            if(isVowel(s.charAt(i))) count++;\n            if(i >= k && isVowel(s.charAt(i - k))) count--;\n            max = Math.max(max, count);\n        }\n        return max;\n    }\n    private boolean isVowel(char c) { return "aeiou".indexOf(c) != -1; }\n}', 'Time: O(N), Space: O(1)', 'Slide checks' FROM problems WHERE leetcode_number = 1456 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Slide character occurrences.', 'Check character counts match sliding frequency window of target.', 'class Solution {\n    public boolean checkInclusion(String s1, String s2) {\n        if(s2.length() < s1.length()) return false;\n        int[] c1 = new int[26], c2 = new int[26];\n        for(int i=0; i<s1.length(); i++){\n            c1[s1.charAt(i) - ''a'']++;\n            c2[s2.charAt(i) - ''a'']++;\n        }\n        if(Arrays.equals(c1, c2)) return true;\n        for(int i=s1.length(); i<s2.length(); i++){\n            c2[s2.charAt(i) - ''a'']++;\n            c2[s2.charAt(i - s1.length()) - ''a'']--;\n            if(Arrays.equals(c1, c2)) return true;\n        }\n        return false;\n    }\n}', 'Time: O(N), Space: O(1)', 'Equal checks' FROM problems WHERE leetcode_number = 567 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Choice tree recursion.', 'Generate choices up to opening brackets, backtrack at leaf results.', 'class Solution {\n    public List<String> generateParenthesis(int n) {\n        List<String> ans = new ArrayList<>();\n        backtrack(ans, "", 0, 0, n);\n        return ans;\n    }\n    private void backtrack(List<String> ans, String curr, int open, int close, int max){\n        if(curr.length() == max * 2) { ans.add(curr); return; }\n        if(open < max) backtrack(ans, curr + "(", open + 1, close, max);\n        if(close < open) backtrack(ans, curr + ")", open, close + 1, max);\n    }\n}', 'Time: O(4^N / N sqrt(N)), Space: O(N) recursion stack', 'Wildcard backtracks' FROM problems WHERE leetcode_number = 22 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Monotonic stack.', 'Maintain indices of decreasing temperatures in stack, resolve days span on popping.', 'class Solution {\n    public int[] dailyTemperatures(int[] temperatures) {\n        int n = temperatures.length;\n        int[] ans = new int[n];\n        Stack<Integer> st = new Stack<>();\n        for(int i=0; i<n; i++){\n            while(!st.isEmpty() && temperatures[i] > temperatures[st.peek()]){\n                int prev = st.pop();\n                ans[prev] = i - prev;\n            }\n            st.push(i);\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(N)', 'Decreasing stacks' FROM problems WHERE leetcode_number = 739 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Alternating level queue scans.', 'DFS/BFS with level counts, reversing nodes list on alternate steps.', 'class Solution {\n    public List<List<Integer>> zigzagLevelOrder(TreeNode root) {\n        List<List<Integer>> ans = new ArrayList<>();\n        if(root == null) return ans;\n        Queue<TreeNode> q = new LinkedList<>();\n        q.add(root);\n        boolean rev = false;\n        while(!q.isEmpty()){\n            int sz = q.size();\n            LinkedList<Integer> level = new LinkedList<>();\n            for(int i=0; i<sz; i++){\n                TreeNode curr = q.poll();\n                if(rev) level.addFirst(curr.val);\n                else level.addLast(curr.val);\n                if(curr.left != null) q.add(curr.left);\n                if(curr.right != null) q.add(curr.right);\n            }\n            ans.add(level); rev = !rev;\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(N)', 'Reverse level queues' FROM problems WHERE leetcode_number = 103 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Swapping node linkages.', 'Recursively adjust pointer bounds to swap pairs.', 'class Solution {\n    public ListNode swapPairs(ListNode head) {\n        if(head == null || head.next == null) return head;\n        ListNode next = head.next;\n        head.next = swapPairs(next.next);\n        next.next = head;\n        return next;\n    }\n}', 'Time: O(N), Space: O(N) stack', 'Pointer bounds logic' FROM problems WHERE leetcode_number = 24 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'K-group pointer reversals.', 'Check remaining nodes list contains K items, reverse section, reconnect recursively.', 'class Solution {\n    public ListNode reverseKGroup(ListNode head, int k) {\n        ListNode curr = head;\n        int count = 0;\n        while(curr != null && count != k) { curr = curr.next; count++; }\n        if(count == k){\n            curr = reverseKGroup(curr, k);\n            while(count-- > 0){\n                ListNode tmp = head.next;\n                head.next = curr;\n                curr = head;\n                head = tmp;\n            }\n            head = curr;\n        }\n        return head;\n    }\n}', 'Time: O(N), Space: O(N/K) stack', 'Recursive segment bounds' FROM problems WHERE leetcode_number = 25 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Merge sort algorithm.', 'Recursively partition array and merge sorted halves.', 'class Solution {\n    public int[] sortArray(int[] nums) {\n        mergeSort(nums, 0, nums.length - 1);\n        return nums;\n    }\n    private void mergeSort(int[] nums, int l, int r){\n        if(l >= r) return;\n        int m = l + (r - l)/2;\n        mergeSort(nums, l, m); mergeSort(nums, m+1, r);\n        merge(nums, l, m, r);\n    }\n    private void merge(int[] nums, int l, int m, int r){\n        int[] temp = new int[r - l + 1];\n        int i = l, j = m + 1, k = 0;\n        while(i <= m && j <= r) temp[k++] = nums[i] <= nums[j] ? nums[i++] : nums[j++];\n        while(i <= m) temp[k++] = nums[i++];\n        while(j <= r) temp[k++] = nums[j++];\n        System.arraycopy(temp, 0, nums, l, temp.length);\n    }\n}', 'Time: O(N log N), Space: O(N)', 'Merge splits' FROM problems WHERE leetcode_number = 912 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Target summation checks.', 'Subtract node value from target, check recursive leaf returns matching 0.', 'class Solution {\n    public boolean hasPathSum(TreeNode root, int targetSum) {\n        if(root == null) return false;\n        if(root.left == null && root.right == null) return targetSum == root.val;\n        return hasPathSum(root.left, targetSum - root.val) || hasPathSum(root.right, targetSum - root.val);\n    }\n}', 'Time: O(N), Space: O(H)', 'Leaf checks' FROM problems WHERE leetcode_number = 112 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Node ancestor search.', 'Retrieve root matches node LCA, look recursively in left and right paths.', 'class Solution {\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        if(root == null || root == p || root == q) return root;\n        TreeNode left = lowestCommonAncestor(root.left, p, q);\n        TreeNode right = lowestCommonAncestor(root.right, p, q);\n        if(left != null && right != null) return root;\n        return left != null ? left : right;\n    }\n}', 'Time: O(N), Space: O(H)', 'Recursive path LCA returns' FROM problems WHERE leetcode_number = 236 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Compare boundary bounds.', 'Recursive validate left < node.val < right limits.', 'class Solution {\n    public boolean isValidBST(TreeNode root) {\n        return validate(root, null, null);\n    }\n    private boolean validate(TreeNode root, Integer min, Integer max){\n        if(root == null) return true;\n        if((min != null && root.val <= min) || (max != null && root.val >= max)) return false;\n        return validate(root.left, min, root.val) && validate(root.right, root.val, max);\n    }\n}', 'Time: O(N), Space: O(H)', 'Null limits' FROM problems WHERE leetcode_number = 98 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Priority queue squared comparisons.', 'Calculate squared coordinate volumes, maintain max-heap sizing of K.', 'class Solution {\n    public int[][] kClosest(int[][] points, int k) {\n        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> (b[0]*b[0] + b[1]*b[1]) - (a[0]*a[0] + a[1]*a[1]));\n        for(int[] p : points){\n            pq.add(p);\n            if(pq.size() > k) pq.poll();\n        }\n        int[][] ans = new int[k][2];\n        for(int i=0; i<k; i++) ans[i] = pq.poll();\n        return ans;\n    }\n}', 'Time: O(N log K), Space: O(K)', 'Heap sorting directions' FROM problems WHERE leetcode_number = 973 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Count character frequencies.', 'Greedy schedule checks using max frequency counters to compute empty spaces.', 'class Solution {\n    public int leastInterval(char[] tasks, int n) {\n        int[] freq = new int[26];\n        for(char c : tasks) freq[c - ''A'']++;\n        Arrays.sort(freq);\n        int maxVal = freq[25] - 1;\n        int idle = maxVal * n;\n        for(int i=24; i>=0 && freq[i] > 0; i--) idle -= Math.min(freq[i], maxVal);\n        return idle > 0 ? idle + tasks.length : tasks.length;\n    }\n}', 'Time: O(N), Space: O(1)', 'Idle calculations' FROM problems WHERE leetcode_number = 621 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Duplicate recursive splits.', 'Backtrack paths, skip duplicates sorting element bounds.', 'class Solution {\n    public List<List<Integer>> subsetsWithDup(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        Arrays.sort(nums);\n        backtrack(ans, new ArrayList<>(), nums, 0);\n        return ans;\n    }\n    private void backtrack(List<List<Integer>> ans, List<Integer> temp, int[] nums, int start){\n        ans.add(new ArrayList<>(temp));\n        for(int i=start; i<nums.length; i++){\n            if(i > start && nums[i] == nums[i-1]) continue;\n            temp.add(nums[i]);\n            backtrack(ans, temp, nums, i+1);\n            temp.remove(temp.size()-1);\n        }\n    }\n}', 'Time: O(2^N), Space: O(N)', 'Skipping duplicates checking indexes' FROM problems WHERE leetcode_number = 90 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Combinations backtracking.', 'Generate arrays combinations recursively selecting items up to limit K.', 'class Solution {\n    public List<List<Integer>> combine(int n, int k) {\n        List<List<Integer>> ans = new ArrayList<>();\n        backtrack(ans, new ArrayList<>(), 1, n, k);\n        return ans;\n    }\n    private void backtrack(List<List<Integer>> ans, List<Integer> temp, int start, int n, int k){\n        if(temp.size() == k) { ans.add(new ArrayList<>(temp)); return; }\n        for(int i=start; i<=n; i++){\n            temp.add(i);\n            backtrack(ans, temp, i+1, n, k);\n            temp.remove(temp.size()-1);\n        }\n    }\n}', 'Time: O(N! / (K! (N-K)!)), Space: O(K)', 'Backtrack size loops' FROM problems WHERE leetcode_number = 77 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Grid DFS area scans.', 'DFS count connected coordinates land items, return max area value.', 'class Solution {\n    public int maxAreaOfIsland(int[][] grid) {\n        int max = 0;\n        for(int r=0; r<grid.length; r++){\n            for(int c=0; c<grid[0].length; c++){\n                if(grid[r][c] == 1) max = Math.max(max, dfs(grid, r, c));\n            }\n        }\n        return max;\n    }\n    private int dfs(int[][] grid, int r, int c){\n        if(r<0 || r>=grid.length || c<0 || c>=grid[0].length || grid[r][c] == 0) return 0;\n        grid[r][c] = 0;\n        return 1 + dfs(grid, r+1, c) + dfs(grid, r-1, c) + dfs(grid, r, c+1) + dfs(grid, r, c-1);\n    }\n}', 'Time: O(R*C), Space: O(R*C)', 'DFS grids visits' FROM problems WHERE leetcode_number = 695 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Double DFS maps.', 'DFS traversal from borders tracking lands that reach both ocean shores.', 'class Solution {\n    public List<List<Integer>> pacificAtlantic(int[][] heights) {\n        List<List<Integer>> ans = new ArrayList<>();\n        int R = heights.length, C = heights[0].length;\n        boolean[][] pac = new boolean[R][C], atl = new boolean[R][C];\n        for(int r=0; r<R; r++) { dfs(heights, r, 0, pac, 0); dfs(heights, r, C-1, atl, 0); }\n        for(int c=0; c<C; c++) { dfs(heights, 0, c, pac, 0); dfs(heights, R-1, c, atl, 0); }\n        for(int r=0; r<R; r++){\n            for(int c=0; c<C; c++){\n                if(pac[r][c] && atl[r][c]) ans.add(Arrays.asList(r, c));\n            }\n        }\n        return ans;\n    }\n    private void dfs(int[][] h, int r, int c, boolean[][] ocean, int prev){\n        if(r<0 || r>=h.length || c<0 || c>=h[0].length || ocean[r][c] || h[r][c] < prev) return;\n        ocean[r][c] = true;\n        dfs(h, r+1, c, ocean, h[r][c]); dfs(h, r-1, c, ocean, h[r][c]);\n        dfs(h, r, c+1, ocean, h[r][c]); dfs(h, r, c-1, ocean, h[r][c]);\n    }\n}', 'Time: O(R*C), Space: O(R*C)', 'Borders traversals' FROM problems WHERE leetcode_number = 417 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Maximum non-adjacent sum.', 'DP relation matching: dp[i] = max(dp[i-1], dp[i-2] + nums[i]).', 'class Solution {\n    public int rob(int[] nums) {\n        int prev1 = 0, prev2 = 0;\n        for(int x : nums){\n            int temp = prev1;\n            prev1 = Math.max(prev1, prev2 + x);\n            prev2 = temp;\n        }\n        return prev1;\n    }\n}', 'Time: O(N), Space: O(1)', 'Non-adjacent sum swaps' FROM problems WHERE leetcode_number = 198 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Segment matching cache.', 'DP array dp[i] matching target word prefix segments present in dictionary.', 'class Solution {\n    public boolean wordBreak(String s, List<String> wordDict) {\n        boolean[] dp = new boolean[s.length() + 1];\n        dp[0] = true;\n        Set<String> set = new HashSet<>(wordDict);\n        for(int i=1; i<=s.length(); i++){\n            for(int j=0; j<i; j++){\n                if(dp[j] && set.contains(s.substring(j, i))){\n                    dp[i] = true; break;\n                }\n            }\n        }\n        return dp[s.length()];\n    }\n}', 'Time: O(N^2), Space: O(N)', 'Substring checks optimization' FROM problems WHERE leetcode_number = 139 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Max XOR trie paths.', 'Insert numbers in binary trie. Query paths selecting opposite bits recursively.', 'class Solution {\n    class Node { Node[] children = new Node[2]; }\n    public int findMaximumXOR(int[] nums) {\n        Node root = new Node();\n        for(int x : nums){\n            Node curr = root;\n            for(int i=31; i>=0; i--){\n                int bit = (x >> i) & 1;\n                if(curr.children[bit] == null) curr.children[bit] = new Node();\n                curr = curr.children[bit];\n            }\n        }\n        int max = 0;\n        for(int x : nums){\n            Node curr = root;\n            int sum = 0;\n            for(int i=31; i>=0; i--){\n                int bit = (x >> i) & 1;\n                int target = bit ^ 1;\n                if(curr.children[target] != null){\n                    sum += (1 << i);\n                    curr = curr.children[target];\n                } else {\n                    curr = curr.children[bit];\n                }\n            }\n            max = Math.max(max, sum);\n        }\n        return max;\n    }\n}', 'Time: O(32 * N), Space: O(32 * N)', 'Bitwise shift limits' FROM problems WHERE leetcode_number = 421 ON CONFLICT (problem_id) DO NOTHING;
